-- Estrutura oficial da Polícia Científica do Rio Grande do Norte, conforme documento anexado.
-- Migration idempotente: não altera usuários, permissões, processos ou módulos.
ALTER TABLE organizational_units_v2 ADD COLUMN IF NOT EXISTS sigla VARCHAR(80);
ALTER TABLE organizational_units_v2 ADD COLUMN IF NOT EXISTS codigo_hierarquico VARCHAR(40);
ALTER TABLE organizational_units_v2 ADD COLUMN IF NOT EXISTS nivel_hierarquico INTEGER;
ALTER TABLE organizational_units_v2 ADD COLUMN IF NOT EXISTS descricao TEXT;
ALTER TABLE organizational_units_v2 ADD COLUMN IF NOT EXISTS status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE organizational_units_v2 DROP CONSTRAINT IF EXISTS organizational_units_v2_tipo_check;
ALTER TABLE organizational_units_v2 ADD CONSTRAINT organizational_units_v2_tipo_check CHECK (tipo IN ('ORGAO', 'CORREGEDORIA', 'DIRETORIA', 'INSTITUTO', 'SUBCOORDENACAO', 'ASSESSORIA', 'NUCLEO', 'SETOR', 'SERVICO', 'LABORATORIO', 'COMISSAO', 'UNIDADE', 'REGIONAL'));
CREATE UNIQUE INDEX IF NOT EXISTS uq_organizational_units_v2_codigo ON organizational_units_v2(codigo_hierarquico);
CREATE INDEX IF NOT EXISTS idx_organizational_units_v2_sigla ON organizational_units_v2(sigla);
CREATE OR REPLACE VIEW organizational_structure_validation AS
SELECT child.id, child.codigo_hierarquico, child.nome, child.sigla, child.tipo, child.nivel_hierarquico, child.parent_id, parent.nome AS unidade_superior, child.ativo, (child.parent_id IS NULL OR parent.id IS NOT NULL) AS possui_superior_valido FROM organizational_units_v2 child LEFT JOIN organizational_units_v2 parent ON parent.id = child.parent_id;
